def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []
    arity = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if (
            verb not in arity
            or len(parts) != arity[verb]
            or any(part == "" for part in parts)
        ):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount_text = parts[-1]
            if not all("0" <= char <= "9" for char in amount_text):
                rejected.append(index)
                continue

            # Parse in small chunks to support arbitrarily long amounts
            # without Python's decimal-string conversion limit.
            amount = 0
            for start in range(0, len(amount_text), 9):
                chunk = amount_text[start:start + 9]
                amount = amount * (10 ** len(chunk)) + int(chunk)

            if verb != "open" and amount == 0:
                rejected.append(index)
                continue

        name = parts[1]

        if verb == "open":
            if name in accounts:
                rejected.append(index)
                continue
            history.append([(name, None)])
            accounts[name] = (amount, False)
            continue

        if name not in accounts:
            rejected.append(index)
            continue

        balance, frozen = accounts[name]

        if verb == "deposit":
            history.append([(name, accounts[name])])
            accounts[name] = (balance + amount, frozen)

        elif verb == "withdraw":
            if frozen or balance < amount:
                rejected.append(index)
                continue
            history.append([(name, accounts[name])])
            accounts[name] = (balance - amount, frozen)

        elif verb == "transfer":
            target = parts[2]
            if (
                name == target
                or target not in accounts
                or frozen
                or balance < amount
            ):
                rejected.append(index)
                continue
            history.append([
                (name, accounts[name]),
                (target, accounts[target]),
            ])
            target_balance, target_frozen = accounts[target]
            accounts[name] = (balance - amount, frozen)
            accounts[target] = (target_balance + amount, target_frozen)

        elif verb == "freeze":
            if frozen:
                rejected.append(index)
                continue
            history.append([(name, accounts[name])])
            accounts[name] = (balance, True)

        elif verb == "unfreeze":
            if not frozen:
                rejected.append(index)
                continue
            history.append([(name, accounts[name])])
            accounts[name] = (balance, False)

    return {
        name: balance
        for name, (balance, frozen) in accounts.items()
    }, rejected
